70	    public HttpResponse handle(ChannelHandlerContext ctx, FullHttpRequest request) throws Exception {
71	
72	        ApiResponse result;
73	        String requestBody = null;
74	        String requestId = null;
75	        try {
76	            HttpMethod method = request.method();
77	            if (HttpMethod.POST.equals(method)) {
78	                requestBody = getBody(request);
79	                ApiRequest apiRequest = parseRequest(requestBody);
80	                requestId = apiRequest.getRequestId();
81	                result = processRequest(ctx, apiRequest);
82	            } else {
83	                result = createResponse(ApiState.REFUSED, "Unsupported http method: " + method.name());
84	            }
85	        } catch (Throwable e) {
86	            result = createResponse(ApiState.FAILED, "Process request error: " + e.getMessage());
87	            logger.error("arthas process http api request error: " + request.uri() + ", request body: " + requestBody, e);
88	        }
89	        if (result == null) {
90	            result = createResponse(ApiState.FAILED, "The request was not processed");
91	        }
92	        result.setRequestId(requestId);
93	
94	        byte[] jsonBytes = JSON.toJSONBytes(result, JSON_FILTERS);
95	
96	        // create http response
97	        DefaultFullHttpResponse response = new DefaultFullHttpResponse(request.protocolVersion(),
98	                HttpResponseStatus.OK, Unpooled.wrappedBuffer(jsonBytes));
99	        response.headers().set(HttpHeaderNames.CONTENT_TYPE, "application/json; charset=utf-8");
100	        return response;
101	    }
