103	    private ApiRequest parseRequest(String requestBody) throws ApiException {
104	        if (StringUtils.isBlank(requestBody)) {
105	            throw new ApiException("parse request failed: request body is empty");
106	        }
107	        try {
108	            //ObjectMapper objectMapper = new ObjectMapper();
109	            //return objectMapper.readValue(requestBody, ApiRequest.class);
110	            return JSON.parseObject(requestBody, ApiRequest.class);
111	        } catch (Exception e) {
112	            throw new ApiException("parse request failed: " + e.getMessage(), e);
113	        }
114	    }
