116	    private ApiResponse processRequest(ChannelHandlerContext ctx, ApiRequest apiRequest) {
117	
118	        String actionStr = apiRequest.getAction();
119	        try {
120	            if (StringUtils.isBlank(actionStr)) {
121	                throw new ApiException("'action' is required");
122	            }
123	            ApiAction action;
124	            try {
125	                action = ApiAction.valueOf(actionStr.trim().toUpperCase());
126	            } catch (IllegalArgumentException e) {
127	                throw new ApiException("unknown action: " + actionStr);
128	            }
129	
130	            //no session required
131	            if (ApiAction.INIT_SESSION.equals(action)) {
132	                return processInitSessionRequest(apiRequest);
133	            }
134	
135	            //required session
136	            Session session = null;
137	            boolean allowNullSession = ApiAction.EXEC.equals(action);
138	            String sessionId = apiRequest.getSessionId();
139	            if (StringUtils.isBlank(sessionId)) {
140	                if (!allowNullSession) {
141	                    throw new ApiException("'sessionId' is required");
142	                }
143	            } else {
144	                session = sessionManager.getSession(sessionId);
145	                if (session == null) {
146	                    throw new ApiException("session not found: " + sessionId);
147	                }
148	                sessionManager.updateAccessTime(session);
149	            }
150	
151	            // 标记所谓的一次性session
152	            if (session == null) {
153	                session = sessionManager.createSession();
154	                session.put(ONETIME_SESSION_KEY, new Object());
155	            }
156	
157	            // 请求到达这里，如果有需要鉴权，则已经在前面的handler里处理过了
158	            // 如果有鉴权取到的 Subject，则传递到 arthas的session里
159	            HttpSession httpSession = HttpSessionManager.getHttpSessionFromContext(ctx);
160	            if (httpSession != null) {
161	                Object subject = httpSession.getAttribute(ArthasConstants.SUBJECT_KEY);
162	                if (subject != null) {
163	                    session.put(ArthasConstants.SUBJECT_KEY, subject);
164	                }
165	                // get userId from httpSession
166	                Object userId = httpSession.getAttribute(ArthasConstants.USER_ID_KEY);
167	                if (userId != null && session.getUserId() == null) {
168	                    session.setUserId((String) userId);
169	                }
170	            }
171	
172	            // set userId from apiRequest if provided
173	            if (!StringUtils.isBlank(apiRequest.getUserId())) {
174	                session.setUserId(apiRequest.getUserId());
175	            }
176	
177	            //dispatch requests
178	            ApiResponse response = dispatchRequest(action, apiRequest, session);
179	            if (response != null) {
180	                return response;
181	            }
182	
183	        } catch (ApiException e) {
184	            logger.info("process http api request failed: {}", e.getMessage());
185	            return createResponse(ApiState.FAILED, e.getMessage());
186	        } catch (Throwable e) {
187	            logger.error("process http api request failed: " + e.getMessage(), e);
188	            return createResponse(ApiState.FAILED, "process http api request failed: " + e.getMessage());
189	        }
190	
191	        return createResponse(ApiState.REFUSED, "Unsupported action: " + actionStr);
192	    }
