        String profilerSoPath = null;
        if (OSUtils.isMac()) {
            // FAT_BINARY support both x86_64/arm64
            profilerSoPath = "async-profiler/libasyncProfiler-mac.dylib";
        }
        if (OSUtils.isLinux()) {
            if (OSUtils.isX86_64()) {
                profilerSoPath = "async-profiler/libasyncProfiler-linux-x64.so";
